bicep:
// ---------------------------------------------------------------------------
// main.bicep — generated by azx (App Intent Service · POC #1, dry-run engine)
// DRY-RUN PREVIEW ONLY — review before deploying. azx made no Azure calls.
// Resolved region: swedencentral
// Advisory estimate: ~$35/mo USD; usage charges may vary.
// ---------------------------------------------------------------------------

targetScope = 'resourceGroup'

@description('Azure region for all resources.')
param location string = 'swedencentral'

@description('Administrator login for the PostgreSQL flexible server.')
param postgresAdminLogin string = 'pgadmin'

@secure()
@description('Administrator password for the PostgreSQL flexible server. Provide at deploy time.')
param postgresAdminPassword string

// Consumption plan — you pay only for running container replicas.
resource appEnv 'Microsoft.App/managedEnvironments@2024-03-01' = {
  name: 'cae-contoso-marketing'
  location: location
  properties: {}
}

// Fallback options considered: Azure App Service (always-on web apps) or Azure Static Web Apps (static/JAMstack).
resource web 'Microsoft.App/containerApps@2024-03-01' = {
  name: 'ca-contoso-marketing'
  location: location
  properties: {
    managedEnvironmentId: appEnv.id
    configuration: {
      ingress: {
        external: true
        targetPort: 3000
      }
    }
    template: {
      containers: [
        {
          name: 'app'
          image: 'mcr.microsoft.com/k8se/quickstart:latest'
          resources: {
            cpu: json('0.5')
            memory: '1.0Gi'
          }
        }
      ]
      scale: {
        minReplicas: 0
        maxReplicas: 3
      }
    }
  }
  dependsOn: [
    appEnv
    openai
    postgres
    storage
  ]
}

// Burstable tier.
resource postgres 'Microsoft.DBforPostgreSQL/flexibleServers@2024-08-01' = {
  name: 'psql-contoso-marketing-27owluk991'
  location: location
  sku: {
    name: 'Standard_B1ms'
    tier: 'Burstable'
  }
  properties: {
      version: '16'
      administratorLogin: postgresAdminLogin
      administratorLoginPassword: postgresAdminPassword
      storage: {
        storageSizeGB: 32
      }
      authConfig: {
        passwordAuth: 'Enabled'
      }
  }
}

resource postgresDb 'Microsoft.DBforPostgreSQL/flexibleServers/databases@2024-08-01' = {
  name: 'psql-contoso-marketing-27owluk991/appdb'
  properties: {
    charset: 'UTF8'
    collation: 'en_US.utf8'
  }
  dependsOn: [
    postgres
  ]
}

// Usage is billed per token. The $0 modeled fixed cost is not a spend cap; actual consumption is unbounded.
resource openai 'Microsoft.CognitiveServices/accounts@2024-10-01' = {
  name: 'oai-contoso-marketing-27owluk991'
  location: location
  kind: 'OpenAI'
  sku: {
    name: 'S0'
  }
  properties: {
    publicNetworkAccess: 'Enabled'
    customSubDomainName: 'oai-contoso-marketing-27owluk991'
  }
}

resource openaiDeployGpt4o62gtzg 'Microsoft.CognitiveServices/accounts/deployments@2024-10-01' = {
  name: 'oai-contoso-marketing-27owluk991/gpt-4o-62gtzg'
  sku: {
    name: 'Standard'
    capacity: 10
  }
  properties: {
    model: {
      format: 'OpenAI'
      name: 'gpt-4o'
      version: '2024-11-20'
    }
  }
  dependsOn: [
    openai
  ]
}

resource storage 'Microsoft.Storage/storageAccounts@2023-05-01' = {
  name: 'stcontosomarke27owluk991'
  location: location
  kind: 'StorageV2'
  sku: {
    name: 'Standard_LRS'
  }
  properties: {
    accessTier: 'Hot'
    supportsHttpsTrafficOnly: true
    minimumTlsVersion: 'TLS1_2'
    allowBlobPublicAccess: false
  }
}

resource blob 'Microsoft.Storage/storageAccounts/blobServices/containers@2023-05-01' = {
  name: 'stcontosomarke27owluk991/default/assets'
  properties: {
    publicAccess: 'None'
  }
  dependsOn: [
    storage
  ]
}

output webAppName string = web.name
output postgresServerName string = postgres.name
output storageAccountName string = storage.name
